def parse_version(version):
    if version.startswith('v'):
        version = version[1:]

    parts = version.split('+')
    main_part = parts[0]
    build = parts[1] if len(parts) > 1 else None

    sub_parts = main_part.split('-')
    base_version_str = sub_parts[0]
    pre_release = sub_parts[1] if len(sub_parts) > 1 else ''

    major, minor, patch = map(int, base_version_str.split('.'))
    if major == 0 and str(major).startswith('0') and len(base_version_str) > 1:
        raise ValueError("leading zeros not allowed")

    pre = []
    for part in pre_release.split('.')):
        try:
            n = int(part)
            pre.append((2, n))
        except ValueError:
            pre.append((1, part))
    return (major, minor, patch), tuple(pre), build


def compare(a, b):
    v1_base, v1_pre, _ = parse_version(a)
    v2_base, v2_pre, _ = parse_version(b)

    if v1_base != v2_base:
        return 1 if v1_base > v2_base else -1

    if v1_pre == v2_pre:
        return 0

    for p1, p2 in zip(v1_pre, v2_pre):
        type1, val1 = p1
        type2, val2 = p2
        if type1 != type2 or val1 != val2:
            # Compare int as numbers, string as lexicographic
            return 1 if (isinstance(val1, int) and isinstance(val2, int)) and val1 > val2 else \
               1 if (not isinstance(val1, int) or not isinstance(val2, int)) and str(val1) > str(val2) else -1

    if len(v1_pre) > len(v2_pre): return 1
    if len(v1_pre) < len(v2_pre): return -1
    return 0


def sort_versions(versions):
    key = lambda v: (parse_version(v)[0], parse_version(v)[1])) # ignore build in key
    return sorted(versions, key=compare)
